  ('Махи гантелями в стороны + дроп-сет на посл. подходе', 'Կողային բարձրացումներ հանտելներով մեջ կողմեր + դրոփ-սեթ վրա վերջին մոտեցումе'),
  ('Махи гантелями в стороны + дроп-сет на посл. подходе (снизить вес +10 повт.)', 'Կողային բարձրացումներ հանտելներով մեջ կողմեր + դրոփ-սեթ վրա վերջին մոտեցումе (снизить քաշ +10 կրկն..)'),
  ('Махи гантелями в стороны сидя', 'Կողային բարձրացումներ հանտելներով մեջ կողմեր նստած'),
  ('Махи гантелями через стороны + частичные повторения на посл. подходе', 'Կողային բարձրացումներ հանտելներով միջով/ամեն կողմեր + частичные կրկնություն վրա վերջին մոտեցումе'),
  ('Махи на нижнем блоке', 'Կողային բարձրացումներ վրա ստորին բլոկ'),
  ('Махи через стороны', 'Կողային բարձրացումներ միջով/ամեն կողմեր'),
  ('Махи через стороны — отдых 20 сек', 'Կողային բարձրացումներ միջով/ամեն կողմեր — հանգիստ 20 վրկ'),
  ('Махи через стороны — отдых 30 сек', 'Կողային բարձրացումներ միջով/ամեն կողմեր — հանգիստ 30 վրկ'),
  ('Метаболический финишер ×3 круга: 20 сек Battle Rope/20 сек отдых, 20 сек быстрые step-up/20 сек отдых, 20 сек SkiErg/40 сек отдых', 'Մետաբոլիկ ավարտիչ ×3 շրջաններ: 20 վրկ Battle Rope/20 վրկ հանգիստ, 20 վրկ արագ step-up/20 վրկ հանգիստ, 20 վրկ SkiErg/40 վրկ հանգիստ'),
  ('Механический дроп-сет (1 подход без отдыха): отжимания с ногами на возвышении → обычные → с колен', 'Մեխանիկական դրոփ-սեթ (1 մոտեցում առանց հանգստի): հրում հատակից հետ ոտքերով բարձրացված մակերեսի վրա → սովորական → հետ ծնկի'),
  ('Молотки', 'Մուրճաձև ծալում'),
  ('Молотки (посл. подход +10 частичных повторений)', 'Մուրճաձև ծալում (վերջին մոտեցում +10 մասնակի կրկնություն)'),
  ('Молотки (посл. подход бицепса: снижение веса +10 повт.)', 'Մուրճաձև ծալում (վերջին մոտեցում բիցեպսի: նվազում քաշ +10 կրկն..)'),
  ('Молотки с гантелями', 'Մուրճաձև ծալում հանտելներով'),
